arguments.command:
python3 << 'EOF'
import glob, re, collections

def load_lines(f):
    with open(f, 'rb') as fh:
        raw = fh.read()
    if raw.startswith(b'\xff\xfe'):
        text = raw.decode('utf-16')
    else:
        text = raw.decode('utf-8', errors='replace')
    return text.splitlines()

for letter in ["A","B"]:
    f = f"production_FARM_{letter}.csv"
    lines = load_lines(f)
    header = lines[3]
    delim = ';' if ';' in header else ','
    cols = [c.strip('\t') for c in header.split(delim)]
    cols[0] = 'timestamp'
    data_lines = [l for l in lines[4:] if l.strip()!='']
    col_weird = collections.defaultdict(set)
    for l in data_lines:
        parts = l.split(delim)
        for i,p in enumerate(parts):
            ps=p.strip()
            if ps=='' or not re.fullmatch(r'-?[\d.,]+', ps):
                if i < len(cols):
                    col_weird[cols[i]].add(ps)
    print(letter, cols)
    for c,v in col_weird.items():
        print("  ", c, v)
EOF

