import glob, re, collections

def load_lines(f):
    with open(f, 'rb') as fh:
        raw = fh.read()
    if raw.startswith(b'\xff\xfe'):
        text = raw.decode('utf-16')
    else:
        text = raw.decode('utf-8', errors='replace')
    return text.splitlines()

for letter in list("ABCDEFGHIJKLMNOPQRSTUVWX"):
    f = f"production_FARM_{letter}.csv"
    lines = load_lines(f)
    header = lines[3]
    delim = ';' if ';' in header else ','
    cols = [c.strip('\t') for c in header.split(delim)]
    cols[0] = 'timestamp'
    data_lines = [l for l in lines[4:] if l.strip()!='']
    # find value column index: we know from calibration json which name; but let's just detect duplicate columns by name to find the "true" one later.
    weird_numbers = []
    for l in data_lines:
        parts = l.split(delim)
        if len(parts) < 2: continue
        for i,p in enumerate(parts):
            if i==0: continue
            ps = p.strip()
            if ps=='' : continue
            if not re.fullmatch(r'-?[\d.,]+', ps):
                continue
            # check convention mismatch
            if delim==';':
                # expect comma decimal; if it has a dot but no comma, and dot is not thousand-sep pattern (3 digits after) flag
                if '.' in ps and ',' not in ps:
                    weird_numbers.append((cols[i] if i<len(cols) else i, ps))
            else:
                if ',' in ps:
                    weird_numbers.append((cols[i] if i<len(cols) else i, ps))
    if weird_numbers:
        print(letter, weird_numbers[:10], "count=",len(weird_numbers))
