python3 << 'EOF'
import glob, re, collections

def load_lines(f):
    with open(f, 'rb') as fh:
        raw = fh.read()
    if raw.startswith(b'\xff\xfe'):
        text = raw.decode('utf-16')
    else:
        text = raw.decode('utf-8', errors='replace')
    return text.splitlines()

for letter in list("ABCDEFGHIJKLMNOPQRSTUVWX"):
    f = f"production_FARM_{letter}.csv"
    lines = load_lines(f)
    header = lines[3]
    delim = ';' if ';' in header else ','
    if delim != ',':
        continue
    cols = [c.strip('\t') for c in header.split(delim)]
    cols[0] = 'timestamp'
    data_lines = [l for l in lines[4:] if l.strip()!='']
    counts = collections.Counter()
    for l in data_lines:
        parts = l.split(delim)
        if len(parts) < 2: continue
        for i,p in enumerate(parts):
            if i==0: continue
            ps = p.strip()
            try:
                v = float(ps)
                if abs(v)>=888888 or v==-999.0 or abs(v- 888888.8)<0.01:
                    counts[(cols[i] if i<len(cols) else i, ps)] += 1
            except:
                pass
    print(letter, counts)
EOF

