import json
import re
from collections import Counter
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo

import pandas as pd

DATASET = "/app/dataset"

WINDOW_START = datetime(2024, 3, 15, 0, 0, 0)
WINDOW_END = datetime(2024, 3, 16, 0, 0, 0)

INVALID_TOKENS = {"", "N/A", "null", "ERR", "timeout", "offline", "NaN", "NULL", "nan"}
SENTINEL_VALUES = (-999.0, 888888.8)

ENERGY_UNIT_TO_KWH = {
    "kwh": 1.0,
    "mwh": 1000.0,
    "wh": 0.001,
    "btu": 0.00029307107,
}
POWER_UNIT_TO_KW = {
    "kw": 1.0,
}


def load_calibration():
    with open(f"{DATASET}/sensors_calibration.json") as f:
        d = json.load(f)
    return d["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def load_farm_registry():
    reg = {}
    with open(f"{DATASET}/farm_registry.csv") as f:
        next(f)
        for line in f:
            line = line.strip()
            if not line:
                continue
            name, fid = line.split(",")
            reg[name.strip().lower()] = fid.strip()
    return reg


def load_farm_timezones():
    tz_by_name = {}
    with open(f"{DATASET}/farms.csv") as f:
        next(f)
        for line in f:
            line = line.rstrip("\n")
            if not line.strip():
                continue
            parts = line.split(",")
            name = parts[0].strip().strip("\t").strip()
            tzname = parts[1].strip()
            tz_by_name[name.lower()] = tzname
    return tz_by_name


def build_farm_id_to_tz():
    reg = load_farm_registry()
    tz_by_name = load_farm_timezones()
    result = {}
    for name, fid in reg.items():
        if name in tz_by_name:
            result[fid] = tz_by_name[name]
    return result


def parse_maintenance_windows(farm_id_to_tz, registry):
    with open(f"{DATASET}/maintenance_notes.txt") as f:
        text = f.read()

    name_to_id = {name: fid for name, fid in registry.items()}

    windows = {}  # farm_id -> list of (utc_start, utc_end)
    paragraphs = [p.strip().replace("\n", " ") for p in text.split("\n\n") if p.strip()]

    day_re = re.compile(r"(\d{1,2})(?:st|nd|rd|th)?\s+of\s+March|March\s+(\d{1,2})(?:st|nd|rd|th)?")
    time_range_re = re.compile(
        r"from\s+(\d{1,2}:\d{2})\s+to\s+(\d{1,2}:\d{2})|"
        r"starting at\s+(\d{1,2}:\d{2})\s+and finishing at\s+(\d{1,2}:\d{2})"
    )

    for para in paragraphs:
        if "local time" not in para:
            continue

        found_farm = None
        for name in name_to_id:
            if name in para.lower():
                found_farm = name_to_id[name]
                break
        if found_farm is None:
            continue

        day_match = day_re.search(para)
        if not day_match:
            continue
        day = int(day_match.group(1) or day_match.group(2))

        time_match = time_range_re.search(para)
        if not time_match:
            continue
        if time_match.group(1):
            start_s, end_s = time_match.group(1), time_match.group(2)
        else:
            start_s, end_s = time_match.group(3), time_match.group(4)

        is_cancelled = "CANCELLED" in para.upper()
        is_completed = "COMPLETED" in para.upper()
        if not is_completed or is_cancelled:
            continue

        sh, sm = map(int, start_s.split(":"))
        eh, em = map(int, end_s.split(":"))

        tzname = farm_id_to_tz.get(found_farm)
        if tzname is None:
            continue
        tz = ZoneInfo(tzname)

        local_start = datetime(2024, 3, day, sh, sm, tzinfo=tz)
        local_end = datetime(2024, 3, day, eh, em, tzinfo=tz)

        utc_start = local_start.astimezone(timezone.utc).replace(tzinfo=None)
        utc_end = local_end.astimezone(timezone.utc).replace(tzinfo=None)

        windows.setdefault(found_farm, []).append((utc_start, utc_end))

    return windows


def parse_timestamp(s):
    s = s.strip()
    if not s:
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None


def parse_number(s, delim):
    s = s.strip()
    if s in INVALID_TOKENS:
        return None
    try:
        if delim == ";" and "," in s:
            s2 = s.replace(".", "").replace(",", ".")
        else:
            s2 = s
        val = float(s2)
    except ValueError:
        return None
    for sentinel in SENTINEL_VALUES:
        if abs(val - sentinel) < 1e-6:
            return None
    return val


def load_farm_file(letter):
    path = f"{DATASET}/production_FARM_{letter}.csv"
    with open(path, "rb") as f:
        raw = f.read()
    if raw.startswith(b"\xff\xfe"):
        text = raw.decode("utf-16")
    else:
        text = raw.decode("utf-8", errors="replace")
    lines = text.splitlines()
    header_line = lines[3]
    delim = ";" if ";" in header_line else ","
    cols = [c.strip("\t") for c in header_line.split(delim)]
    cols[0] = "timestamp"

    data_lines = [l for l in lines[4:] if l.strip() != ""]
    records = []
    for l in data_lines:
        parts = l.split(delim)
        if len(parts) != len(cols):
            continue
        records.append(parts)

    df = pd.DataFrame(records, columns=cols)
    df = df.drop_duplicates()
    return df, delim


def compute_interval_hours(timestamps):
    ts_sorted = sorted(t for t in timestamps if t is not None)
    deltas = []
    for i in range(1, len(ts_sorted)):
        d = (ts_sorted[i] - ts_sorted[i - 1]).total_seconds()
        if d > 0:
            deltas.append(d)
    if not deltas:
        return None
    mode_delta = Counter(deltas).most_common(1)[0][0]
    return mode_delta / 3600.0


def process_farm(letter, calibration, maintenance_windows):
    farm_id = f"FARM_{letter}"
    cal = calibration[farm_id]
    value_col = cal["calibration_data"]["value_column_name"]
    offset = cal["calibration_data"]["calibration_offset"]
    reading_type = cal["sensor_info"]["reading_type"]
    unit = cal["sensor_info"]["unit"].lower()

    df, delim = load_farm_file(letter)

    if value_col not in df.columns:
        return 0

    timestamps = [parse_timestamp(s) for s in df["timestamp"]]
    temps = [parse_number(s, delim) for s in df["inverter_temperature_C"]]
    raw_values = [parse_number(s, delim) for s in df[value_col]]

    # spike -> emergency shutdown exclusion windows: (T, T+45min]
    spike_windows = []
    for ts, temp in zip(timestamps, temps):
        if ts is not None and temp is not None and temp > 85.0:
            spike_windows.append((ts, ts + timedelta(minutes=45)))

    def in_spike_window(ts):
        for start, end in spike_windows:
            if start < ts <= end:
                return True
        return False

    farm_maint_windows = maintenance_windows.get(farm_id, [])

    def in_maintenance_window(ts):
        for start, end in farm_maint_windows:
            if start <= ts < end:
                return True
        return False

    if reading_type == "energy":
        factor = ENERGY_UNIT_TO_KWH.get(unit)
        interval_hours = None
    else:
        factor = POWER_UNIT_TO_KW.get(unit)
        interval_hours = compute_interval_hours(timestamps)

    if factor is None:
        return 0

    total = 0.0
    for ts, raw_val in zip(timestamps, raw_values):
        if ts is None or raw_val is None:
            continue
        if not (WINDOW_START <= ts < WINDOW_END):
            continue
        if in_spike_window(ts):
            continue
        if in_maintenance_window(ts):
            continue

        true_val = raw_val - offset
        if true_val < 0:
            continue

        if reading_type == "energy":
            kwh = true_val * factor
        else:
            kwh = true_val * factor * interval_hours

        total += kwh

    return round(total)


def answer() -> dict:
    calibration = load_calibration()
    registry = load_farm_registry()
    farm_id_to_tz = build_farm_id_to_tz()
    maintenance_windows = parse_maintenance_windows(farm_id_to_tz, registry)

    result = {}
    for letter in "ABCDEFGHIJKLMNOPQRSTUVWX":
        farm_id = f"FARM_{letter}"
        result[farm_id] = process_farm(letter, calibration, maintenance_windows)
    return result


if __name__ == "__main__":
    import json as _json

    with open("/app/answer.json", "w") as f:
        _json.dump(answer(), f, default=list)

